import 'package:flutter/material.dart';import 'package:pos_app/core/app_services.dart';import 'package:pos_app/features/catalog/data/catalog_repository.dart';import 'package:pos_app/shared/presentation/database_list_screen.dart';class ProductsScreen extends StatelessWidget{const ProductsScreen({super.key});@override Widget build(BuildContext context)=>DatabaseListScreen(title:'Productos',query:'SELECT id,code,name,sale_price_cents,minimum_stock,active FROM products ORDER BY name',action:(c)async{final v=await textForm(c,'Nuevo producto',['Código','Nombre','Precio centavos','Stock mínimo']);if(v!=null){await CatalogRepository(appDatabase).addProduct(code:v[0],name:v[1],salePriceCents:int.parse(v[2]),minimumStock:int.tryParse(v[3])??0);}});}
